package com.witchersbestiary.merchant;
import net.minecraft.entity.*;import net.minecraft.entity.mob.PathAwareEntity;import net.minecraft.entity.player.PlayerEntity;import net.minecraft.entity.data.*;import net.minecraft.item.*;import net.minecraft.nbt.*;import net.minecraft.util.*;import net.minecraft.util.math.BlockPos;import net.minecraft.world.World;
import software.bernie.geckolib.animatable.GeoEntity;import software.bernie.geckolib.animatable.instance.AnimatableInstanceCache;import software.bernie.geckolib.animation.*;
import java.util.*;

public final class ArcaneMerchant extends PathAwareEntity implements GeoEntity {
 public enum Mode { VILLAGE, WANDERING }
 public static final class Offer {public final String id;public final ItemStack result;public final long price;public int stock;Offer(String id,ItemStack result,long price,int stock){this.id=id;this.result=result;this.price=price;this.stock=stock;}}
 private static final TrackedData<Boolean> TRADING=DataTracker.registerData(ArcaneMerchant.class,TrackedDataHandlerRegistry.BOOLEAN);
 private final AnimatableInstanceCache cache=software.bernie.geckolib.util.GeckoLibUtil.createInstanceCache(this);
 private Mode mode=Mode.WANDERING;private String village="";private BlockPos home;private long lifetime,restockAt;private final List<Offer> offers=new ArrayList<>();
 public ArcaneMerchant(EntityType<? extends PathAwareEntity> type,World world){super(type,world);setPersistent();}
 public Mode mode(){return mode;}public String village(){return village;}public List<Offer> offers(){if(offers.isEmpty()&&!getWorld().isClient)generateOffers();return Collections.unmodifiableList(offers);}
 public void village(String identity,BlockPos pos){mode=Mode.VILLAGE;village=identity;home=pos.toImmutable();offers.clear();generateOffers();}
 public boolean trading(){return getWorld() instanceof net.minecraft.server.world.ServerWorld w&&w.getPlayers(p->p.currentScreenHandler instanceof MerchantHandler h&&h.merchant()==this).size()>0;}
 @Override protected void initDataTracker(DataTracker.Builder b){super.initDataTracker(b);b.add(TRADING,false);}
 @Override protected void initGoals(){goalSelector.add(0,new net.minecraft.entity.ai.goal.SwimGoal(this));goalSelector.add(4,new net.minecraft.entity.ai.goal.WanderAroundFarGoal(this,.5){public boolean canStart(){return !trading()&&(home==null||getPos().squaredDistanceTo(home.toCenterPos())<144)&&super.canStart();}public boolean shouldContinue(){return !trading()&&(home==null||getPos().squaredDistanceTo(home.toCenterPos())<196)&&super.shouldContinue();}});goalSelector.add(3,new net.minecraft.entity.ai.goal.LookAtEntityGoal(this,PlayerEntity.class,6));goalSelector.add(6,new net.minecraft.entity.ai.goal.LookAroundGoal(this));}
 @Override protected ActionResult interactMob(PlayerEntity player,Hand hand){if(player instanceof net.minecraft.server.network.ServerPlayerEntity p&&p.isSneaking()){com.witchersbestiary.fist.Tournaments.open(p,this);return ActionResult.SUCCESS;}if(player instanceof net.minecraft.server.network.ServerPlayerEntity p&&!com.witchersbestiary.fist.FistFights.busy(p)){p.sendMessage(net.minecraft.text.Text.translatable("tournament.witchersbestiary.hint"),false);getNavigation().stop();p.openHandledScreen(new net.fabricmc.fabric.api.screenhandler.v1.ExtendedScreenHandlerFactory<Integer>(){public Integer getScreenOpeningData(net.minecraft.server.network.ServerPlayerEntity player){return getId();}public net.minecraft.text.Text getDisplayName(){return getName();}public net.minecraft.screen.ScreenHandler createMenu(int sync,net.minecraft.entity.player.PlayerInventory inventory,PlayerEntity owner){return new MerchantHandler(sync,inventory,getId());}});}return ActionResult.SUCCESS;}
 @Override public void tick(){super.tick();if(getWorld().isClient)return;boolean active=trading();dataTracker.set(TRADING,active);if(active){getNavigation().stop();return;}if(mode==Mode.VILLAGE&&home!=null&&age%100==0&&getPos().squaredDistanceTo(home.toCenterPos())>100)getNavigation().startMovingTo(home.getX()+.5,home.getY(),home.getZ()+.5,.65);if(mode==Mode.VILLAGE&&getWorld().getTime()>=restockAt){for(var o:offers())o.stock=Math.max(o.stock,8);restockAt=getWorld().getTime()+48000;}if(mode==Mode.WANDERING&&++lifetime>48000&&age%200==0&&getWorld().getClosestPlayer(this,48)==null)discard();}
 private void add(String item,long price,int stock){var id=Identifier.of(item.contains(":")?item:"witchersbestiary:"+item);var value=net.minecraft.registry.Registries.ITEM.get(id);if(value!=Items.AIR)offers.add(new Offer(id.toString(),new ItemStack(value),price,stock));}
 private void generateOffers(){add("minecraft:glass_bottle",2,16);add("minecraft:red_mushroom",3,12);add("bone_dust",5,12);add("drowner_essence",12,8);add("ghoul_claw",10,8);add("necrophage_oil",52,4);add("necrophage_elixir",64,3);if(mode==Mode.WANDERING){add("minecraft:bread",6,12);add("minecraft:cooked_beef",12,8);add("minecraft:cooked_porkchop",12,8);add("minecraft:golden_carrot",24,6);add("griffin_feather",180,2);add("gravebound_steel_fragment",260,2);
 var stockRandom=new Random(getUuid().getLeastSignificantBits());if(stockRandom.nextInt(4)==0){String[][] swords={{"steel_hunter_sword","2500"},{"silver_witcher_sword","4500"},{"grave_blade","7000"}};var sword=swords[stockRandom.nextInt(swords.length)];add(sword[0],Long.parseLong(sword[1]),1);}
 String[][] rare={{"wraith_essence","24"},{"katakan_essence","30"},{"hybrid_essence","26"},{"ogroid_essence","26"},{"cursed_oil","72"},{"vampire_elixir","90"}};var choices=new ArrayList<>(List.of(rare));Collections.shuffle(choices,new Random(getUuid().getMostSignificantBits()));for(int i=0;i<3;i++)add(choices.get(i)[0],Long.parseLong(choices.get(i)[1]),2);}restockAt=getWorld().getTime()+48000;}
 @Override public void writeCustomDataToNbt(NbtCompound n){super.writeCustomDataToNbt(n);offers();n.putString("MerchantMode",mode.name());n.putString("MerchantVillage",village);if(home!=null)n.putLong("MerchantHome",home.asLong());n.putLong("MerchantAge",lifetime);n.putLong("MerchantRestock",restockAt);var list=new NbtList();for(var o:offers){var row=new NbtCompound();row.putString("Id",o.id);row.put("Item",o.result.encode(getRegistryManager()));row.putLong("Price",o.price);row.putInt("Stock",o.stock);list.add(row);}n.put("MerchantOffers",list);}
 @Override public void readCustomDataFromNbt(NbtCompound n){super.readCustomDataFromNbt(n);mode=n.getString("MerchantMode").equals("VILLAGE")?Mode.VILLAGE:Mode.WANDERING;village=n.getString("MerchantVillage");home=n.contains("MerchantHome")?BlockPos.fromLong(n.getLong("MerchantHome")):null;lifetime=Math.max(0,n.getLong("MerchantAge"));restockAt=n.getLong("MerchantRestock");offers.clear();var list=n.getList("MerchantOffers",10);for(int i=0;i<Math.min(32,list.size());i++){var row=list.getCompound(i);var stack=ItemStack.fromNbt(getRegistryManager(),row.getCompound("Item")).orElse(ItemStack.EMPTY);if(!stack.isEmpty()&&row.getLong("Price")>0&&row.getInt("Stock")>=0)offers.add(new Offer(row.getString("Id"),stack,row.getLong("Price"),Math.min(64,row.getInt("Stock"))));}}
 @Override public void registerControllers(AnimatableManager.ControllerRegistrar r){r.add(new AnimationController<>(this,"merchant",4,event->event.setAndContinue(RawAnimation.begin().thenLoop("animation.merchant."+(dataTracker.get(TRADING)?"trade":event.isMoving()?"walk":"idle")))));}
 @Override public AnimatableInstanceCache getAnimatableInstanceCache(){return cache;}
}
